#include <LiquidCrystal.h>

// Инициализация библиотеки: (RS, E, D4, D5, D6, D7)
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  // Задаем размер экрана: 16 столбцов, 2 строки
  lcd.begin(16, 2);

  // Выводим приветствие
  lcd.setCursor(0, 0);
  lcd.print("Privet, Arduino!");
}

void loop() {
  // Выводим время работы в секундах на вторую строку
  lcd.setCursor(0, 1);
  lcd.print("Sec: ");
  lcd.print(millis() / 1000);
}
